(function(){
  const ORDW=['','first','second','third','fourth','fifth','sixth','seventh','eighth','ninth','tenth','eleventh','twelfth'];
  const FING=['','thumb','index finger','middle finger','ring finger','little finger'],TOE=['','big toe','second toe','third toe','fourth toe','little toe'];
  const VERT=[];for(let i=1;i<=7;i++)VERT.push(['C'+i,i===1?'atlas':i===2?'axis':ORDW[i]+' cervical vertebra']);
  for(let i=1;i<=12;i++)VERT.push(['T'+i,ORDW[i]+' thoracic vertebra']);for(let i=1;i<=5;i++)VERT.push(['L'+i,ORDW[i]+' lumbar vertebra']);
  const WORD={occipital:'occipital bone',temporal:'temporal bone',frontal:'frontal bone',parietal:'parietal bone',sphenoid:'sphenoid bone',nasal:'nasal bone',
    lacrimal:'lacrimal bone',zygomatic:'zygomatic bone',palatine:'palatine bone',hyoid:'hyoid bone',hip:'hip bone',sternum:'body of sternum',xiphoid:'xiphoid process',
    navicular:'navicular bone of foot',cuboid:'cuboid bone',medialcuneiform:'medial cuneiform bone',intermediatecuneiform:'intermediate cuneiform bone',lateralcuneiform:'lateral cuneiform bone'};
  function one(c){
    let m;
    if(m=c.match(/^([CTL])(\d+)$/))return [VERT.find(v=>v[0]===c)[1]];
    if(m=c.match(/^R(\d+)$/))return [ORDW[+m[1]]+' rib'];
    if(m=c.match(/^MC(\d)$/))return [ORDW[+m[1]]+' metacarpal bone'];
    if(m=c.match(/^MT(\d)$/))return [ORDW[+m[1]]+' metatarsal bone'];
    if(m=c.match(/^([PMD])P(\d)$/))return [{P:'proximal',M:'middle',D:'distal'}[m[1]]+' phalanx of '+FING[+m[2]]];
    if(m=c.match(/^T([PMD])(\d)$/))return [{P:'proximal',M:'middle',D:'distal'}[m[1]]+' phalanx of '+TOE[+m[2]]];
    return [WORD[c]||c];
  }
  function expand(tok){
    let m=tok.match(/^([CTL]\d+)-([CTL]\d+)$/);
    if(m){const a=VERT.findIndex(v=>v[0]===m[1]),b=VERT.findIndex(v=>v[0]===m[2]);return VERT.slice(a,b+1).map(v=>v[1])}
    m=tok.match(/^([A-Z]+?)(\d+)-[A-Z]*?(\d+)$/);
    if(m){const out=[];for(let i=+m[2];i<=+m[3];i++)out.push(...one(m[1]+i));return out}
    return one(tok);
  }
  const NAMEP={C:'C',T:'T',L:'L'};
  function label(tok){
    let m=tok.match(/^([CTL]\d+)-([CTL]\d+)$/);if(m)return `Vertebrae ${m[1]}–${m[2]}`;
    if(/^[CTL]\d+$/.test(tok))return tok==='C1'?'Atlas (C1)':tok==='C2'?'Axis (C2)':`Vertebra ${tok}`;
    m=tok.match(/^R(\d+)(?:-R?(\d+))?$/);if(m)return m[2]?`Ribs ${m[1]}–${m[2]}`:`Rib ${m[1]}`;
    m=tok.match(/^MC(\d)(?:-(\d))?$/);if(m)return m[2]?`Metacarpals ${m[1]}–${m[2]}`:`Metacarpal ${m[1]}`;
    m=tok.match(/^MT(\d)(?:-(\d))?$/);if(m)return m[2]?`Metatarsals ${m[1]}–${m[2]}`:`Metatarsal ${m[1]}`;
    m=tok.match(/^([PMD])P(\d)(?:-(\d))?$/);if(m){const k={P:'Proximal',M:'Middle',D:'Distal'}[m[1]];return m[3]?`${k} phalanges, fingers ${m[2]}–${m[3]}`:`${k} phalanx, ${FING[+m[2]]}`}
    m=tok.match(/^T([PMD])(\d)(?:-(\d))?$/);if(m){const k={P:'Proximal',M:'Middle',D:'Distal'}[m[1]];return m[3]?`${k} phalanges, toes ${m[2]}–${m[3]}`:`${k} phalanx, ${TOE[+m[2]]}`}
    const w=WORD[tok]||tok;return w.charAt(0).toUpperCase()+w.slice(1).replace(/^Hip bone$/,'Hip bone (os coxae)');
  }
  window.ATT={expand,label};
})();

